//! Immutable prior-release wire expectations, never regenerated by record mode.
use std::path::PathBuf;

use serde::Deserialize;
use sha2::{Digest, Sha256};

use super::{replay_corpus, Corpus};
mod agent_list_privacy;
mod desktop_privacy;
mod desktop_privacy_tests;
mod lifecycle_results;

#[derive(Deserialize)]
struct Manifest {
    version: u32,
    releases: Vec<Release>,
}
#[derive(Deserialize)]
struct Release {
    name: String,
    source_commit: String,
    fixtures: Vec<Fixture>,
}
#[derive(Deserialize)]
struct Fixture {
    file: String,
    sha256: String,
    cases: usize,
    selected_case_ids: Vec<String>,
}

fn directory() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/retained-clients")
}

fn corpora() -> Vec<Corpus> {
    let manifest: Manifest =
        serde_json::from_slice(&std::fs::read(directory().join("manifest.json")).unwrap()).unwrap();
    assert_eq!(manifest.version, 1);
    assert_eq!(manifest.releases.len(), 2);
    let mut corpora = Vec::new();
    let mut privacy_additions = 0;
    let mut lifecycle_additions = 0;
    let mut agent_list_privacy_additions = 0;
    for release in manifest.releases {
        let expected = match release.name.as_str() {
            "previous" => "93d4a199a3d36d47f5a89f9117d2bc735900bf4c",
            "current" => "4f03c35a80322673ec00df7a3b6b9399015f5a68",
            _ => panic!("unknown retained release"),
        };
        assert_eq!(release.source_commit, expected);
        assert_eq!(release.fixtures.len(), 3);
        for fixture in release.fixtures {
            assert!(!fixture.file.contains('/'));
            let bytes = std::fs::read(directory().join(&fixture.file)).unwrap();
            assert_eq!(format!("{:x}", Sha256::digest(&bytes)), fixture.sha256);
            let mut corpus: Corpus = serde_json::from_slice(&bytes).unwrap();
            assert_eq!(corpus.version, 1);
            assert_eq!(corpus.cases.len(), fixture.cases);
            assert_eq!(
                corpus.cases.iter().map(|case| &case.id).collect::<Vec<_>>(),
                fixture.selected_case_ids.iter().collect::<Vec<_>>()
            );
            // The existing upgrade harness binds TCP; this slice deliberately cannot call it.
            assert!(corpus.cases.iter().all(|case| {
                case.response.body_kind == super::BodyKind::Json
                    || case.response.body_kind == super::BodyKind::Empty
            }));
            assert!(corpus
                .cases
                .iter()
                .all(|case| !case.operation.ends_with("/desktop/ws")));
            // Verify immutable release bytes before adding reviewed privacy
            // expectations. Replay still compares the complete response exactly.
            privacy_additions +=
                desktop_privacy::apply(&release.source_commit, &fixture.file, &mut corpus);
            lifecycle_additions +=
                lifecycle_results::apply(&release.source_commit, &fixture.file, &mut corpus);
            agent_list_privacy_additions +=
                agent_list_privacy::apply(&release.source_commit, &fixture.file, &mut corpus);
            corpora.push(corpus);
        }
    }
    assert_eq!(
        corpora
            .iter()
            .map(|corpus| corpus.cases.len())
            .sum::<usize>(),
        112
    );
    assert_eq!(privacy_additions, 12);
    assert_eq!(lifecycle_additions, 8);
    assert_eq!(agent_list_privacy_additions, 8);
    corpora
}

#[tokio::test]
async fn retained_current_and_previous_clients_match_develop_handlers_without_network() {
    for mut corpus in corpora() {
        // Always false: neither public-contract recorder environment variable can rewrite these.
        replay_corpus(&mut corpus, false, false).await;
    }
}

#[tokio::test]
async fn retained_oracle_rejects_route_status_header_and_response_field_drift() {
    for mutation in 0..4 {
        let mut corpus = corpora().remove(0);
        let case = corpus
            .cases
            .iter_mut()
            .find(|case| case.id == "agent-read")
            .unwrap();
        match mutation {
            0 => case.request.path = "/api/v1/agents/agt_missing".into(),
            1 => case.response.status = 202,
            2 => {
                case.response
                    .headers
                    .insert("content-type".into(), "text/plain".into());
            }
            3 => case.response.body["id"] = "changed_agent".into(),
            _ => unreachable!(),
        }
        let result =
            tokio::spawn(async move { replay_corpus(&mut corpus, false, false).await }).await;
        assert!(
            result.is_err_and(|error| error.is_panic()),
            "mutation {mutation} escaped the oracle"
        );
    }
}
